SourceCode.Declaration:
/// <summary>
/// One request shape for every operation of HSMobileOpsOrderCreateService; each reads the members it needs. Dates are yyyy-MM-dd.
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderRequest
{
    str dataAreaId;
    str userName;
    str deviceId;
    str idempotencyKey;
    str vendorAccount;
    str siteId;
    str warehouseId;
    str fromWarehouseId;
    str toWarehouseId;
    str deliveryDate;
    str shipDate;
    str receiveDate;
    str itemId;
    str configId;
    str sizeId;
    str colorId;
    str styleId;
    int skip;
    int take;
    str purchId;
    str returnReasonCode;
    str rmaNumber;
    str returnActionId;
    boolean groupByLocation;
    str linesJson;
    List lines;
}

Method.Source:
