/// <summary>
/// The lines, read from LinesJson. Not a data member itself: a list of a custom class does
/// not bind on the way in (JObject cast failure - see HSMobileOpsPostRequest.parmLinesJson).
/// </summary>
public List parmLines(List _value = lines)
{
    lines = _value;
    if (!lines && linesJson)
    {
        lines = HSMobileOpsOrderLine::listFromJson(linesJson);
    }
    return lines;
}

/// <summary>
/// The order lines as a JSON array of HSMobileOpsOrderLine's members.
/// </summary>
[DataMemberAttribute('LinesJson')]
public str parmLinesJson(str _value = linesJson)
{
    linesJson = _value;
    return linesJson;
}

